.2,w=S[758],q="Murlocs at the Gates",npc="Breton Samuels",k="giver"},["data rescue"]={c=S[69],x=-4824.6,y=-1265.4,w="Ironforge",q="Data Rescue",npc="Master Mechanic Castpipe",k="giver"},["mythology of the titans"]={c=S[69],x=-4635.7,y=-1303.4,w="Ironforge",q="Mythology of the Titans",npc="Librarian Mae Paledust",k="giver"},["oh brother..."]={c=S[69],x=-8241.4,y=590.1,w=S[532],q="Oh Brother...",npc=S[910],k="giver"},["open the maw"]={c=S[69],x=-3779.6,y=-2515.2,w="Wetlands",q="Open the Maw",npc="Deathstalker Agent",k="giver"},["power overwhelming"]={c=S[69],x=-8941,y=1069.6,w=S[532],q="Power Overwhelming",npc="High Sorcerer Andromath",k="giver"},["deviate hides"]={q="Deviate Hides",npc="Nalpak",k="dungeon",d=S[986],note="Nalpak stands in the alcove above the cavern entrance; the pin is the dungeon entrance."},["opportunistic education"]={q="Opportunistic Education",npc="Quest giver position unknown",k="dungeon",d="city of dalaran",note="The giver has no known map position, so the pin is the dungeon entrance."},["an unholy alliance"]={c=S[69],x=1286.5,y=334,w="Undercity",q="An Unholy Alliance",npc="Varimathras (turn-in)",k="giver",note="This quest starts from an item drop in Razorfen Downs; the pin is where you hand it in."}},specs={{id="retribution",name="Retribution",token="RET",title="Retribution | WoW Forever Paladin Field Guide",nav={{id="overview",x=S[919]},{id="journey",x=S[740]},{id="talents",x=S[629]},{id="stats",x=S[805]},{id="combat",x=S[806]},{id="macros",x=S[777]},{id="dungeons",x=S[707]},{id="professions",x=S[741]},{id="crafting",x=S[725]},{id="questgear",x=S[682]},{id=S[625],x=S[868]}},asideNote=S[104],talentString="050050002000000005030000000000000005233301001301351",ranks={{tree="Holy",name=S[759],r=5,max=5},{tree="Holy",name=S[786],r=5,max=5},{tree="Holy",name=S[857],r=2,max=2},{tree="Protection",name=S[505],r=5,max=5},{tree="Protection",name="Precision",r=3,max=3},{tree="Retribution",name="Benediction",r=5,max=5},{tree="Retribution",name=S[683],r=2,max=2},{tree="Retribution",name="Conviction",r=3,max=3},{tree="Retribution",name=S[912],r=3,max=3},{tree="Retribution",name="Vindication",r=3,max=3},{tree="Retribution",name=S[869],r=1,max=1},{tree="Retribution",name=S[1001],r=1,max=1},{tree="Retribution",name=S[735],r=3,max=3},{tree="Retribution",name="Repentance",r=1,max=1},{tree="Retribution",name="Vengeance",r=3,max=3},{tree="Retribution",name=S[891],r=5,max=5},{tree="Retribution",name=S[1002],r=1,max=1}},order={{l1=10,l2=14,tree="Holy",name=S[759],r1=1,r2=5,max=5},{l1=15,l2=19,tree="Holy",name=S[786],r1=1,r2=5,max=5},{l1=20,l2=21,tree="Holy",name=S[857],r1=1,r2=2,max=2},{l1=22,l2=26,tree="Protection",name=S[505],r1=1,r2=5,max=5},{l1=27,l2=29,tree="Protection",name="Precision",r1=1,r2=3,max=3},{l1=30,l2=34,tree="Retribution",name="Benediction",r1=1,r2=5,max=5},{l1=35,l2=36,tree="Retribution",name="Conviction",r1=1,r2=2,max=3},{l1=37,l2=38,tree="Retribution",name=S[683],r1=1,r2=2,max=2},{l1=39,l2=39,tree="Retribution",name="Conviction",r1=3,r2=3,max=3},{l1=40,l2=42,tree="Retribution",name=S[912],r1=1,r2=3,max=3},{l1=43,l2=43,tree="Retribution",name=S[869],r1=1,r2=1,max=1},{l1=44,l2=44,tree="Retribution",name="Vindication",r1=1,r2=1,max=3},{l1=45,l2=47,tree="Retribution",name=S[735],r1=1,r2=3,max=3},{l1=48,l2=48,tree="Retribution",name=S[1001],r1=1,r2=1,max=1},{l1=49,l2=49,tree="Retribution",name="Vindication",r1=2,r2=2,max=3},{l1=50,l2=50,tree="Retribution",name="Repentance",r1=1,r2=1,max=1},{l1=51,l2=53,tree="Retribution",name="Vengeance",r1=1,r2=3,max=3},{l1=54,l2=54,tree="Retribution",name="Vindication",r1=3,r2=3,max=3},{l1=55,l2=59,tree="Retribution",name=S[891],r1=1,r2=5,max=5},{l1=60,l2=60,tree="Retribution",name=S[1002],r1=1,r2=1,max=1}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[684]},{t="h1",x="Retribution",sub=S[778]},{t="p",s="lede",x="Level with a slow two-handed weapon: Seal of Command, Holy Strike and Judgement carry the damage, Champion of the Light turns your Intellect into spell damage, and Unsealed Wrath opens up Seal swapping at 60."},{t="pills",list={S[864],"Solo questing and melee damage",S[742]}},{t="anchor",id="journey"},{t="kicker",x=S[920]},{t="h2",x=S[589]},{t="p",x="These stages follow the talent order below. Retribution is the recommended solo leveling build, and with a shield and Seal of Fury it can still tank an early dungeon."},{t="p",s="level",x="1–19 · Strength and Seals"},{t="p",x="Keep Seal of Righteousness and Devotion Aura up, Judge on cooldown from 4 (Judgement no longer consumes your Seal) and use Holy Strike from 6. Divine Strength reaches 5/5 at 14 for 10% more Strength, then Improved Seals 5/5 by 19 adds 15% to Seal and Judgement damage. Hammer of Justice at 8 buys time for Holy Light."},{t="p",s="level",x="20–39 · Consecration and crit"},{t="p",x="Consecration, Exorcism, Flash of Light and Blessing of Kings arrive at 20, so Holy Conduit (20–21) cuts their mana cost by 40%. Divine Intellect 5/5 by 26 and Precision 3/3 by 29 add Intellect and 3% hit. Benediction 5/5 by 34 makes instant spells 10% cheaper; Conviction 3/3 (6% critical strike chance on all attacks and spells) and Improved Judgement 2/2 finish at 39. Start Verigan’s Fist (Alliance) or Wolfsbane (Horde) at 20."},{t="p",s="level",x="40–60 · Command and Champion"},{t="p",x="Sanctified Judgement 3/3 by 42 refunds Seal mana and Seal of Command arrives at 43. Vindication (44, 49 and 54), Two-Handed Weapon Specialization (45–47, up to 6% more Holy and Physical damage and less threat), Sacred Arbiter (48), Repentance (50) and Vengeance (51–53, up to 5 stacks) follow. Champion of the Light 5/5 by 59 turns 60% of your Intellect into spell damage and shortens Hammer of Wrath’s cast, and Unsealed Wrath completes the build at 60."},{t="anchor",id="talents"},{t="kicker",x=S[630]},{t="h2",x=S[864]},{t="p",x=S[76]},{t="widget",w="talents"},{t="h4",s="summary",x=S[708]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[609]},{t="p",x=S[144]},{t="widget",w="order"},{t="p",s="notice",x="Unsealed Wrath stores a copy of your active Seal on each melee hit (up to 3 stacks for 15 seconds); hitting with a different Seal gives every stored copy its normal chance to activate. Swap from Seal of Command to Seal of Righteousness, wait for the stored Seal to be consumed, then swap back. It costs extra mana, so keep one damage Seal on ordinary quest enemies. Champion of the Light adds spell damage equal to 60% of your Intellect."},{t="anchor",id="stats"},{t="kicker",x=S[807]},{t="h2",x=S[662]},{t="p",x="Your two-handed weapon matters most: Seals and your auto attacks scale with weapon damage. Champion of the Light turns part of your Intellect into spell damage, so Intellect is useful too."},{t="h3",x=S[892]},{t="stat",i=1,b=S[1009],x="a slow two-hander"},{t="stat",i=2,b="Strength",x="attack power"},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Intellect",x="mana and spell damage through Champion of the Light"},{t="p",s="small",x="Seal of Command procs about 7 times a minute at any weapon speed, so slower weapons deal more per proc."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[1009],x=""},{t="stat",i=2,b="Hit chance",x="to 8%"},{t="stat",i=3,b="Expertise",x="to 6.5%"},{t="stat",i=4,b="Spell power",x=""},{t="stat",i=5,b="Strength",x=""},{t="p",s="small",x="Builds with Holy Shock lean on spell power instead: weapon damage, hit to 8%, spell power, critical strike, then expertise, and they prefer faster weapons with Seal of Righteousness."},{t="p",s="notice",x="Melee hit cap: 8% for special attacks against raid bosses. Expertise removes dodge at 6.5% and parry at 14% (parry only matters from the front). The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[663]},{t="h2",x=S[726]},{t="p",x="Treat this as a priority list, not a fixed loop. Leave out what you have not learned yet: Consecration and Exorcism at 20, Seal of Command at 43, Hammer of Wrath at 44 and Unsealed Wrath at 60."},{t="h4",x="Buffs and Seal"},{t="p",x="Keep Blessing of Might up (Blessing of Kings from 20; long Blessings last an hour in Forever) and Devotion or Retribution Aura. Keep one damage Seal active: Seal of Righteousness until 43, then Seal of Command with a slow weapon. Do not refresh the Seal early; let it run out first."},{t="h4",x="Open with the Crusader on long fights"},{t="p",x="On an enemy that will live a while, Judge Seal of the Crusader first for the Holy damage taken debuff, then switch to your damage Seal. From 49, Sacred Arbiter lets Holy Strike refresh every Judgement effect on the target."},{t="h4",x="Judgement and Holy Strike on cooldown"},{t="p",x="Judgement is off the global cooldown, so press it alongside other abilities. Holy Strike is cheap and on a short cooldown. With Seal of Command, Judgement deals double damage to a stunned or incapacitated target, so pair it with Hammer of Justice or Repentance."},{t="h4",x="Consecration and Exorcism"},{t="p",x="Consecration is your area damage but costs almost twice as much as Judgement and Holy Strike together, even with Holy Conduit; use it on two or more enemies or when mana is high. Exorcism is a strong instant spell against Undead and Demons and pulls them from 30 yards."},{t="h4",x="Finish and recover"},{t="p",x="From 44, Hammer of Wrath finishes an enemy below 20% health, which also stops runners. Let auto-attacks finish enemies that are nearly dead and spend spare mana on Holy Light rather than drinking."},{t="h4",x="Emergencies"},{t="p",x="Hammer of Justice stuns while you heal. Divine Protection (6) and Divine Shield (34) make you immune, Blessing of Freedom breaks roots and slows, and Lay on Hands (10) heals you fully at the cost of all your mana."},{t="abil",names={S[869],"Seal of Righteousness","Seal of the Crusader","Judgement","Holy Strike",S[1024],"Exorcism","Hammer of Wrath","Repentance"}},{t="h3",x="Equipment and weapons"},{t="p",x="Weapon damage per second comes first. With similar damage, a slower two-hander gives bigger hits for Seal of Command and Holy Strike; a fast weapon or one with an on-hit proc suits Seal of Righteousness. Verigan’s Fist (Alliance) and Wolfsbane (Horde) from the level 20 class quests are among the best two-handers before 30."},{t="p",x="After weapon damage, look for Strength, hit and critical strike, then spell damage and Intellect, which grow stronger once Champion of the Light is trained. Prefer mail until plate is trained at 40."},{t="h3",x="Supplies, Blessings and group utility"},{t="p",x="Carry water and food: you heal yourself with mana, so convert leftover mana into Holy Light between fights. First Aid bandages heal without mana. In groups, Blessing of Kings is the strongest default; Retribution Aura helps a tank with packs."},{t="p",x="Paladins have no interrupt and no slow. Hammer of Justice and Repentance are your control."},{t="anchor",id="macros"},{t="kicker",x=S[779]},{t="h2",x=S[559]},{t="p",x=S[70]},{t="p",s="notice",x=S[74]},{t="macro",n=S[727],x=S[299],code=S[379]},{t="macro",n=S[760],x=S[162],code=S[397]},{t="macro",n=S[631],x=S[108],code=S[225]},{t="macro",n=S[685],x=S[196],code=S[252]},{t="macro",n=S[761],x=S[262],code=S[286]},{t="macro",n=S[824],x=S[136],code=S[326]},{t="macro",n=S[610],x=S[312],code=S[226]},{t="macro",n=S[590],x=S[191],code=S[219]},{t="macro",n=S[591],x=S[240],code=S[414]},{t="macro",n="Repentance and Judgement",x="Incapacitates a Humanoid and judges in the same press. Judgement is off the global cooldown, and judging immediately does not break Repentance; with Seal of Command the Judgement deals double damage to the incapacitated target.",code="#showtooltip Repentance\n/cast [harm,nodead] Repentance\n/cast [harm,nodead] Judgement"},{t="macro",n="Seal of Command / Shift Seal of Righteousness",x="For Unsealed Wrath seal swapping from 60 in this build: normal press for Seal of Command, Shift for Seal of Righteousness. Swap only after your last stored Seal has been consumed by a melee hit.",code="#showtooltip\n/cast [mod:shift] Seal of Righteousness; Seal of Command"},{t="macro",n="Hammer of Wrath finisher",x="From 44: use on an enemy below 20% health, especially one that flees. It has a cast time, so press it before the enemy runs out of range.",code="#showtooltip Hammer of Wrath\n/startattack [harm,nodead]\n/cast [harm,nodead] Hammer of Wrath"},{t="macro",n="Two-hander / one-hander and shield",x="Swaps between your two-handed weapon and a one-hander plus shield, for tanking an early dungeon with Seal of Fury. Replace the three names with the exact item names from your bags.",code="#showtooltip\n/equip [noworn:two-hand] TWO-HANDED WEAPON NAME; ONE-HANDED WEAPON NAME\n/equip [worn:two-hand] SHIELD NAME"},{t="p",s="small",x=S[392]},{t="anchor",id="dungeons"},{t="kicker",x=S[870]},{t="h2",x=S[611]},{t="p",x=S[83]},{t="widget",w="rarity"},{t="p",s="notice",x=S[84]},{t="p",s="notice",x=S[44]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[664]},{t="h2",x=S[608]},{t="p",x=S[98]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[709]},{t="h2",x=S[592]},{t="p",x=S[38]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[665]},{t="h2",x=S[542]},{t="p",x=S[39]},{t="widget",w="quest"},{t="anchor",id=S[625]},{t="kicker",x=S[871]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[123]}},dungeons={{n=S[406],lr="13–18",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n=S[345],lr="13–18",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n=S[122],lr="15–20",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[825],st=S[37],no=S[41],it={}}},t={{id=286981,n=S[874],mob=S[21],st=S[819],no=S[19]}},no={S[42],S[32],S[25]}}},{n=S[189],lr="17–24",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[624],st=S[37],no=S[41],it={}}},t={},no={S[42],S[79],S[25]}}},{n=S[