n=S[963],lr="48–53",st=S[86],no=S[28],ba=false},{n=S[666],lr="50–60",st=S[86],no=S[28],ba=false},{n=S[859],lr="52–60",st=S[86],no=S[28],ba=false},{n="Dire Maul",lr="54–60",st=S[86],no=S[193],ba=false},{n=S[743],lr="55–60",st=S[86],no=S[28],ba=false},{n=S[921],lr="55–60",st=S[86],no=S[28],ba=false},{n="Scholomance",lr="58–60",st=S[86],no=S[28],ba=false},{n="Stratholme",lr="58–60",st=S[86],no=S[28],ba=false},{n=S[860],lr="58–60",st=S[86],no=S[28],ba=false},{n=S[744],lr="59–60",st=S[86],no=S[28],ba=false}}},{id="protection",name="Protection",token="PROT",title="Protection | WoW Forever Paladin Field Guide",nav={{id="overview",x=S[919]},{id="journey",x=S[740]},{id="talents",x=S[629]},{id="stats",x=S[805]},{id="combat",x=S[806]},{id="macros",x=S[777]},{id="dungeons",x=S[707]},{id="professions",x=S[741]},{id="crafting",x=S[725]},{id="questgear",x=S[682]},{id=S[625],x=S[868]}},asideNote=S[104],talentString="05005000200000000553001020131015315021",ranks={{tree="Holy",name=S[759],r=5,max=5},{tree="Holy",name=S[786],r=5,max=5},{tree="Holy",name=S[857],r=2,max=2},{tree="Protection",name=S[505],r=5,max=5},{tree="Protection",name="Redoubt",r=5,max=5},{tree="Protection",name="Precision",r=3,max=3},{tree="Protection",name=S[616],r=1,max=1},{tree="Protection",name=S[893],r=2,max=2},{tree="Protection",name=S[872],r=1,max=1},{tree="Protection",name=S[865],r=3,max=3},{tree="Protection",name=S[1025],r=1,max=5},{tree="Protection",name="Holy Shield",r=1,max=1},{tree="Protection",name="Reckoning",r=5,max=5},{tree="Protection",name="Iron Creed",r=3,max=3},{tree="Protection",name="Shieldsworn",r=1,max=1},{tree="Retribution",name="Deflection",r=5,max=5},{tree="Retribution",name=S[683],r=2,max=2},{tree="Retribution",name="Conviction",r=1,max=3}},order={{l1=10,l2=14,tree="Protection",name="Redoubt",r1=1,r2=5,max=5},{l1=15,l2=17,tree="Protection",name="Precision",r1=1,r2=3,max=3},{l1=18,l2=19,tree="Protection",name=S[505],r1=1,r2=2,max=5},{l1=20,l2=21,tree="Protection",name=S[893],r1=1,r2=2,max=2},{l1=22,l2=22,tree="Protection",name=S[616],r1=1,r2=1,max=1},{l1=23,l2=24,tree="Protection",name=S[505],r1=3,r2=4,max=5},{l1=25,l2=25,tree="Protection",name=S[872],r1=1,r2=1,max=1},{l1=26,l2=28,tree="Protection",name=S[865],r1=1,r2=3,max=3},{l1=29,l2=29,tree="Protection",name=S[1025],r1=1,r2=1,max=5},{l1=30,l2=30,tree="Protection",name="Holy Shield",r1=1,r2=1,max=1},{l1=31,l2=35,tree="Protection",name="Reckoning",r1=1,r2=5,max=5},{l1=36,l2=38,tree="Protection",name="Iron Creed",r1=1,r2=3,max=3},{l1=39,l2=39,tree="Protection",name=S[505],r1=5,r2=5,max=5},{l1=40,l2=40,tree="Protection",name="Shieldsworn",r1=1,r2=1,max=1},{l1=41,l2=45,tree="Retribution",name="Deflection",r1=1,r2=5,max=5},{l1=46,l2=47,tree="Retribution",name=S[683],r1=1,r2=2,max=2},{l1=48,l2=52,tree="Holy",name=S[759],r1=1,r2=5,max=5},{l1=53,l2=57,tree="Holy",name=S[786],r1=1,r2=5,max=5},{l1=58,l2=59,tree="Holy",name=S[857],r1=1,r2=2,max=2},{l1=60,l2=60,tree="Retribution",name="Conviction",r1=1,r2=1,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[684]},{t="h1",x="Protection",sub=S[778]},{t="p",s="lede",x="Tank with a one-handed weapon and shield: Seal of Fury makes Judgement a taunt, Consecration holds packs, and Redoubt, Reckoning and Holy Shield turn blocks into mana, extra attacks and threat."},{t="pills",list={S[701],"Dungeon tanking and group pulls",S[742]}},{t="anchor",id="journey"},{t="kicker",x=S[920]},{t="h2",x=S[589]},{t="p",x="These stages follow the talent order below. Protection is the build for regular dungeon tanking and for pulling several melee enemies at once; mana is your limit, so carry water."},{t="p",s="level",x="1–19 · Blocks and hit"},{t="p",x="Keep Seal of Righteousness and Devotion Aura up while you level; from 10, Seal of Fury and Righteous Fury give you a taunt and Holy threat. Redoubt reaches 5/5 at 14 (up to 30% more block chance after a hit), Precision 3/3 by 17 adds 3% hit, and Divine Intellect (18–19) starts adding Intellect for a deeper mana pool."},{t="p",s="level",x="20–39 · Shield and Bulwark"},{t="p",x="Shield Specialization 2/2 by 21 makes blocks restore 4% mana (once every 3 seconds). Templar’s Bulwark at 22 absorbs damage equal to your maximum health (it is a Magic effect, so enemies can dispel it), Swift Judgement at 25 gives a second taunt, Improved Righteous Fury 3/3 by 28 cuts damage taken by 9% and Anticipation (29) adds Defense. Holy Shield at 30, Reckoning 5/5 by 35 and Iron Creed 3/3 by 38 follow, and Divine Intellect reaches 5/5 at 39."},{t="p",s="level",x="40–60 · Shieldsworn and support"},{t="p",x="Shieldsworn at 40 lets Holy Strike hit with your shield, triggering Holy Shield and Shield Specialization without spending them, and lowers its cooldown by 4 seconds. Plate is trained at 40. Deflection 5/5 by 45 and Improved Judgement 2/2 by 47 come next; Divine Strength, Improved Seals and Holy Conduit fill the Holy tree from 48 to 59, and Conviction takes the last point at 60."},{t="anchor",id="talents"},{t="kicker",x=S[630]},{t="h2",x=S[701]},{t="p",x=S[76]},{t="widget",w="talents"},{t="h4",s="summary",x=S[708]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[609]},{t="p",x=S[144]},{t="widget",w="order"},{t="p",s="notice",x="Seal of Fury is the core of this build: with it active, Judgement and Swift Judgement force the enemy to attack you for 3 seconds, and the Seal grants absorb shields while you wear a shield. Reckoning stores up to four extra attacks from blocks and critical hits taken. Templar’s Bulwark and Divine Protection both apply Forbearance, so you get one or the other per minute."},{t="anchor",id="stats"},{t="kicker",x=S[807]},{t="h2",x=S[662]},{t="p",x="Protection Paladin threat comes from spells, so spell power is part of the tank set. Stamina and Defense keep you alive."},{t="h3",x=S[892]},{t="stat",i=1,b="Stamina",x=""},{t="stat",i=2,b="Armor",x="shield and plate"},{t="stat",i=3,b="Strength",x=""},{t="stat",i=4,b="Spell power",x="threat from Seals and Consecration"},{t="stat",i=5,b="Intellect",x="mana"},{t="p",s="small",x="Retribution gear works for questing alone; keep a shield and some spell power for dungeons."},{t="h3",x="At level 60"},{t="stat",i=1,b="Stamina",x=""},{t="stat",i=2,b="Defense",x="to 440"},{t="stat",i=3,b="Spell power",x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Strength",x=""},{t="p",s="small",x="Block chance, armor and Agility add mitigation. Some estimates put spell power and melee hit (8%) above Defense for a threat-focused set."},{t="p",s="notice",x="Defense 440 makes a level 63 boss unable to land a critical hit on you. Spell hit cap: 17% against raid bosses; melee hit cap: 8%. The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[663]},{t="h2",x=S[726]},{t="p",x="Treat this as a priority list, not a fixed loop. Seal of Fury and Righteous Fury arrive at 10, Consecration at 20, Templar’s Bulwark at 22, Swift Judgement at 25 and Holy Shield at 30."},{t="h4",x="Buffs before the pull"},{t="p",x="Keep Righteous Fury on for Holy threat; Improved Righteous Fury also cuts damage taken by 9%. Use Devotion Aura, or Retribution Aura while leveling. Give the group Blessing of Kings, or Wisdom for a healer who needs mana."},{t="h4",x="Seal of Fury always"},{t="p",x="Keep Seal of Fury active. It adds Holy damage to your attacks, gives absorb shields while you wear a shield, and turns Judgement into a taunt. Swap to Seal of Righteousness only when you need damage and no taunt."},{t="h4",x="Taunt with Judgement"},{t="p",x="Target or mouse over the enemy attacking a party member and Judge. If Judgement is on cooldown, Swift Judgement (from 25) judges the Seal again on its own cooldown. Hammer of Justice is your backup when no taunt is ready."},{t="h4",x="Consecration and Holy Strike"},{t="p",x="Gather the pack, then place Consecration as mana allows; it hits harder on the first four enemies that enter it. Use Holy Strike on the enemy that needs more threat; Iron Creed adds 30% threat and 6% damage reduction for 6 seconds."},{t="h4",x="Holy Shield and blocks"},{t="p",x="From 30, keep Holy Shield up against melee: 30% more block chance and Holy damage on each block. Blocks feed Redoubt, Shield Specialization mana and Reckoning extra attacks. With Shieldsworn (40), Holy Strike triggers Holy Shield without spending charges and lets you block spells for 6 seconds."},{t="h4",x="Defensive cooldowns"},{t="p",x="Use Templar’s Bulwark before a pull overwhelms your healer. It applies Forbearance for 1 minute, which also blocks Divine Shield and Divine Protection. Keep immunities for true emergencies and cancel them quickly, because enemies turn to your group while you are immune."},{t="abil",names={"Seal of Fury","Righteous Fury","Judgement",S[872],"Holy Strike",S[1024],"Holy Shield",S[616]}},{t="h3",x="Equipment and threat"},{t="p",x="Armor and Stamina first, then Defense, block chance and block value; Redoubt, Shield Specialization and Holy Shield all trigger on blocks. Spell damage raises your Holy damage and threat, and Intellect gives you more mana to spend."},{t="p",x="Use a one-handed weapon and shield; a faster weapon applies Seal of Fury more often. Prefer mail until plate is trained at 40, and do not give up a lot of armor for a small damage bonus."},{t="h3",x="Supplies and dungeon tips"},{t="p",x="Bring water; Consecration and Judgement are expensive. Start with small pulls, break line of sight to bring casters to you, and use Exorcism to pull Undead and Demons from range."},{t="p",x="Paladins have no regular interrupt, so ask a party member to interrupt dangerous casts when Hammer of Justice is on cooldown. Judge Seal of Wisdom on a boss (from 38) for mana returns, then switch back to Seal of Fury."},{t="anchor",id="macros"},{t="kicker",x=S[779]},{t="h2",x=S[559]},{t="p",x=S[70]},{t="p",s="notice",x=S[74]},{t="macro",n=S[727],x=S[299],code=S[379]},{t="macro",n=S[760],x=S[162],code=S[397]},{t="macro",n=S[631],x=S[108],code=S[225]},{t="macro",n=S[685],x=S[196],code=S[252]},{t="macro",n=S[761],x=S[262],code=S[286]},{t="macro",n=S[824],x=S[136],code=S[326]},{t="macro",n=S[610],x=S[312],code=S[226]},{t="macro",n=S[590],x=S[191],code=S[219]},{t="macro",n=S[591],x=S[240],code=S[414]},{t="macro",n="Mouseover Judgement taunt",x="With Seal of Fury active, Judgement forces the enemy under your pointer to attack you. Use it on whatever turns to a party member.",code="#showtooltip Judgement\n/cast [@mouseover,harm,nodead][harm,nodead] Judgement"},{t="macro",n="Judgement / Shift Swift Judgement",x="Swift Judgement (from 25) judges a Seal without consuming it and does not share Judgement’s cooldown, so it is your second taunt with Seal of Fury.",code="#showtooltip\n/cast [mod:shift,harm,nodead] Swift Judgement; [harm,nodead] Judgement"},{t="macro",n="Templar's Bulwark / Shift Divine Protection",x="Templar's Bulwark (from 22) absorbs damage equal to your maximum health for 8 seconds. Both spells apply Forbearance, so choose one. Stops your current cast.",code="#showtooltip\n/stopcasting\n/cast [mod:shift] Divine Protection; Templar's Bulwark"},{t="macro",n="Holy Shield and Holy Strike",x="Holy Shield (from 30) adds 30% block chance for four blocks. With Shieldsworn at 40, Holy Strike hits with your shield and triggers Holy Shield without using a charge.",code="#showtooltip Holy Shield\n/cast Holy Shield\n/startattack [harm,nodead]"},{t="p",s="small",x=S[392]},{t="anchor",id="dungeons"},{t="kicker",x=S[870]},{t="h2",x=S[611]},{t="p",x=S[83]},{t="widget",w="rarity"},{t="p",s="notice",x=S[84]},{t="p",s="notice",x=S[44]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[664]},{t="h2",x=S[608]},{t="p",x=S[98]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[709]},{t="h2",x=S[592]},{t="p",x=S[38]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[665]},{t="h2",x=S[542]},{t="p",x=S[39]},{t="widget",w="quest"},{t="anchor",id=S[625]},{t="kicker",x=S[871]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[123]}},dungeons={{n=S[406],lr="13–18",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n=S[345],lr="13–18",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n=S[122],lr="15–20",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[825],st=S[37],no=S[41],it={}}},t={{id=286981,n=S[874],mob=S[21],st=S[819],no=S[19]}},no={S[42],S[32],S[25]}}},{n=S[189],lr="17–24",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[624],st=S[37],no=S[41],it={}}},t={},no={S[42],S[79],S[25]}}},{n=S[143],lr="17–26",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[728],st=S[37],no=S[121],it={{id=5443,n=S[768]},{id=5444,n=S[947]}}}},t={{id=1951,n=S[946],mob=S[21],st=S[26],no=S[19]}},no={S[42],S[32],S[25]}}},{n=S[129],lr="22–30",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[808],st=S[37],no=S[41],it={}},{n="Gefell",st=S[37],no=S[41],it={}},{n="Gemela",st=S[37],no=S[41],it={}}},t={{id=1482,n="Shadowfang",mob=S[21],st=S[26],no=S[19]},{id=1483,n=S[1015],mob=S[21],st=S[26],no=S[19]},{id=2807,n=S[992],mob=S[21],st=S[26],no=S[19]}},no={S[42],S[32],S[25]}}},{n=S[280],lr="24–32",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[649],st=S[37],no=S[121],it={{id=3228,n=S[822]}}}},t={{id=1076,n=S[749],mob=S[21],st=S[26],no=S[19]}},no={S[42],S[32],S[25]}}},{n=S[111],lr="24–32",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={{id=1454,n=S[927],mob=S[21],st=S[26],no=S[19]},{id=3416,n=S[877],mob=S[21],st=S[26],no=S[19]}},no={S[31],S[32],S[25]}}},{n=S[141],lr="26–31",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n=S[224],lr="28–33",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={},t={},no={S[31],S[79],S[25]}}},{n="Gnomeregan",lr="29–38",st=S[52],no=S[14],ba=true,ra={ck=S[78],r={{n=S[638],st=S[37],no=S[121],it={}}},t={{id=9485,n="Vibroblade",mob=S[21],st=S[26],no=S[19]},{